import{encode,concat,uint32be}from"./buffer_utils.js";import{checkEncCryptoKey}from"./crypto_key.js";import{digest}from"./helpers.js";function lengthAndInput(t){return concat(uint32be(t.length),t)}async function concatKdf(t,e,n){const r=e>>3,c=Math.ceil(r/32),i=new Uint8Array(32*c);for(let e=1;e<=c;e++){const r=new Uint8Array(4+t.length+n.length);r.set(uint32be(e),0),r.set(t,4),r.set(n,4+t.length);const c=await digest("sha256",r);i.set(c,32*(e-1))}return i.slice(0,r)}export async function deriveKey(t,e,n,r,c=new Uint8Array,i=new Uint8Array){checkEncCryptoKey(t,"ECDH"),checkEncCryptoKey(e,"ECDH","deriveBits");const a=lengthAndInput(encode(n)),o=lengthAndInput(c),s=lengthAndInput(i),u=uint32be(r),h=new Uint8Array,l=concat(a,o,s,u,h);return concatKdf(new Uint8Array(await crypto.subtle.deriveBits({name:t.algorithm.name,public:t},e,getEcdhBitLength(t))),r,l)}function getEcdhBitLength(t){return"X25519"===t.algorithm.name?256:Math.ceil(parseInt(t.algorithm.namedCurve.slice(-3),10)/8)<<3}export function allowed(t){switch(t.algorithm.namedCurve){case"P-256":case"P-384":case"P-521":return!0;default:return"X25519"===t.algorithm.name}}